package org.jsoup.safety;

import java.io.*;
import java.math.*;
import java.util.*;
import org.jsoup.Document;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Attribute;
import org.jsoup.nodes.Attributes;
import org.jsoup.nodes.DataNode;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Node;
import org.jsoup.nodes.TextNode;
import org.jsoup.parser.ParseErrorList;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.safety.Cleaner;
import org.jsoup.select.NodeTraversor;
import org.jsoup.select.NodeVisitor;
import org.junit.*;
import org.junit.Test;
import static org.jsoup.safety.CleanerTestUtils.*;
import static org.junit.Assert.*;

public class Cleaner_isValid_TriageGen0Test {

    @Test
    public void testIsValid_NullDirtyDocument() {
        Cleaner cleaner = new Cleaner(new Whitelist());
        Document dirtyDocument = null;
        assertTrue(cleaner.isValid(dirtyDocument));
    }

    @Test
    public void testIsValid_EmptyDirtyDocument() {
        Cleaner cleaner = new Cleaner(new Whitelist());
        Document dirtyDocument = Document.createShell("https://example.com");
        assertTrue(cleaner.isValid(dirtyDocument));
    }

    @Test
    public void testIsValid_SingleNodeDirtyDocument() {
        Cleaner cleaner = new Cleaner(new Whitelist());
        Document dirtyDocument = Document.createShell("https://example.com")
            .body().appendChild(Element.Factory.fromString("<p>Hello World!</p>"));
        assertTrue(cleaner.isValid(dirtyDocument));
    }

    @Test
    public void testIsValid_MultipleNodesDirtyDocument() {
        Cleaner cleaner = new Cleaner(new Whitelist());
        Document dirtyDocument = Document.createShell("https://example.com")
            .body().appendChild(Element.Factory.fromString("<p>Hello World!</p>"))
            .body().appendChild(Element.Factory.fromString("<p>This is a test!</p>"));
        assertTrue(cleaner.isValid(dirtyDocument));
    }

    @Test
    public void testIsValid_DiscardedNodesDirtyDocument() {
        Cleaner cleaner = new Cleaner(new Whitelist());
        Document dirtyDocument = Document.createShell("https://example.com")
            .body().appendChild(Element.Factory.fromString("<script>alert('XSS')</script>"));
        assertFalse(cleaner.isValid(dirtyDocument));
    }

    @Test
    public void testIsValid_CopySafeNodesDirtyDocument() {
        Cleaner cleaner = new Cleaner(new Whitelist());
        Document dirtyDocument = Document.createShell("https://example.com")
            .body().appendChild(Element.Factory.fromString("<p>Hello World!</p>"));
        Document clean = cleaner.copySafeNodes(dirtyDocument.body(), dirtyDocument.body());
        assertTrue(cleaner.isValid(dirtyDocument));
    }

    @Test
    public void testIsValid_CopySafeNodesDirtyDocument_DiscardedNodes() {
        Cleaner cleaner = new Cleaner(new Whitelist());
        Document dirtyDocument = Document.createShell("https://example.com")
            .body().appendChild(Element.Factory.fromString("<script>alert('XSS')</script>"));
        Document clean = cleaner.copySafeNodes(dirtyDocument.body(), dirtyDocument.body());
        assertFalse(cleaner.isValid(dirtyDocument));
    }
}
